/**
 * mkraftman-windows-pc-media-control v1.0.4
 * Uses Relmtech.Keyboard toggle to send actual media key events.
 */
class MkraftmanWindowsPCMediaControl extends HTMLElement {
  constructor(){super();this.attachShadow({mode:"open"});this._config=null;this._hass=null;this._el={};this._built=false}
  static getStubConfig(){return{}}
  setConfig(c){this._config=c||{};if(this._built)this._update();else if(this._hass)this._build()}
  getCardSize(){return 3}getGridOptions(){return{rows:3,columns:12,min_rows:3,min_columns:6}}
  set hass(h){this._hass=h;if(!this._config)return;if(!this._built){this._build();return}}
  _build(){if(this._built||!this._hass||!this._config)return;const s=this.shadowRoot;s.innerHTML=`<style>:host{display:block;--mc-fg:var(--primary-text-color,#fff)}ha-card{position:relative;overflow:hidden;height:100%;box-sizing:border-box;background:#132532}.bg{position:absolute;inset:0}.bg-color{position:absolute;inset:0;background-color:#132532}.bg-image{position:absolute;right:0;top:0;bottom:0;background-size:cover;background-position:center;background-image:url('/local/images/windows.png')}.bg-gradient{position:absolute;right:0;top:0;bottom:0;background:linear-gradient(to right,#132532 0%,transparent 100%)}.player{position:relative;z-index:1;display:flex;flex-direction:column;padding:16px;height:100%;box-sizing:border-box;color:var(--mc-fg)}.name{font-size:18px;font-weight:500;opacity:.85;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;color:var(--mc-fg);margin-bottom:8px}.controls{display:flex;align-items:center;justify-content:center;width:100%;padding:4px 0;gap:4px;flex:1}.ctrl{background:none;border:none;cursor:pointer;border-radius:50%;display:flex;align-items:center;justify-content:center;padding:10px;flex:1;max-width:72px;transition:background-color .15s;color:var(--mc-fg);-webkit-tap-highlight-color:transparent;outline:none}.ctrl ha-icon{--mdc-icon-size:40px;color:var(--mc-fg)}.ctrl.pp{max-width:132px}.ctrl.pp ha-icon{--mdc-icon-size:65px}</style><ha-card><div class="bg"><div class="bg-color"></div><div class="bg-image" id="bgImage"></div><div class="bg-gradient" id="bgGrad"></div></div><div class="player"><div class="name">Windows PC Living Room</div><div class="controls"><button class="ctrl" id="prev"><ha-icon icon="mdi:skip-previous"></ha-icon></button><button class="ctrl pp" id="pp"><ha-icon icon="mdi:play-pause"></ha-icon></button><button class="ctrl" id="next"><ha-icon icon="mdi:skip-next"></ha-icon></button></div></div></ha-card>`;this._el={card:s.querySelector("ha-card"),bgImage:s.getElementById("bgImage"),bgGrad:s.getElementById("bgGrad")};s.getElementById("prev").addEventListener("click",()=>{this._sendKey("media_prev_track")});s.getElementById("pp").addEventListener("click",()=>{this._sendKey("media_play_pause")});s.getElementById("next").addEventListener("click",()=>{this._sendKey("media_next_track")});this._built=true;this._updateBgSize();this._resizeObserver=new ResizeObserver(()=>{this._updateBgSize()});this._resizeObserver.observe(this._el.card)}
  _updateBgSize(){if(!this._el.card||!this._el.bgImage)return;const h=this._el.card.offsetHeight;if(h>0){this._el.bgImage.style.width=h+"px";this._el.bgGrad.style.width=h+"px"}}
  _sendKey(key){if(!this._hass)return;this._hass.callService("unified_remote","call",{remote_id:"Relmtech.Keyboard",action:"toggle",extras:{Values:[{Value:key}]}})}
  _update(){}
  connectedCallback(){if(this._hass&&this._config&&!this._built)this._build()}
  disconnectedCallback(){if(this._resizeObserver){this._resizeObserver.disconnect();this._resizeObserver=null}}
}
customElements.define("mkraftman-windows-pc-media-control",MkraftmanWindowsPCMediaControl);
window.customCards=window.customCards||[];window.customCards.push({type:"mkraftman-windows-pc-media-control",name:"Mkraftman Windows PC Media Control",description:"Transport controls for Windows PC via Unified Remote."});
